#include <iostream>
#include <cstdlib>
#include <ctime>

using std::cout;
using std::cin;
using std::endl;

int main()
{
    srand((unsigned int)time(NULL));

    int iStage = 0;
    int iSelect;

    while (iStage < 10)
    {
        cout << "강화하시겠습니까?" << endl;
        cout << "1. 예\t2. 아니오" << endl;
        cout << "Select: ";
        cin >> iSelect;

        if ((iSelect == 1 || iSelect == 2) == false)
        {
            cout << "잘못된 값을 입력하였습니다." << endl;
            continue;
        }
        else if (iSelect == 2)
            break;

        int iPercent = rand() % 100;

        if (iPercent < 100 - iStage * 10)
        {
            cout << "강화 성공!! " << iStage << " -> " << iStage + 1 << endl;
            iStage++;
        }
        else
        {
            cout << "강화 실패!! " << iStage << " -> ";
            if (iStage > 0)
                iStage--;
            cout << iStage << endl;
        }
    }

    if (iStage == 10)
        cout << "아이템이 최고 단계에 도달하였습니다." << endl;
    else
        cout << "강화를 종료하였습니다." << endl;

    return 0;
}
